// Checks for EventService.stream lease lifecycle, driven through the
// Source/Lease interfaces declared in src/source.ts.
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Builds a Source whose Lease serves a scripted read sequence. A script entry
// is a string value, `null` for end of stream, or an Error instance which
// makes that read() reject. Leases are instrumented so every open(), read()
// and close() is observable; both open() and close() can be made to fail.
function makeSource(script, { failOpen = undefined, failClose = undefined } = {}) {
  const state = { opens: 0, closes: 0, readLog: [], closeLog: [] };
  const source = {
    open: async () => {
      state.opens++;
      if (failOpen) throw failOpen;
      const queue = script.slice();
      return {
        read: async () => {
          const token = queue.length ? queue.shift() : null;
          state.readLog.push(token instanceof Error ? 'read!' : token === null ? 'END' : token);
          if (token instanceof Error) throw token;
          return token;
        },
        close: async () => {
          state.closeLog.push('close');
          state.closes++;
          if (failClose) throw failClose;
        },
      };
    },
  };
  return { source, state };
}

// Mapper fixture: records the values it receives in order, uppercases them,
// and can be made to fail on a specific value with a fixed error instance.
function makeMapper({ log = undefined, fixedFail = undefined } = {}) {
  const fail = fixedFail;
  return (value) => {
    if (log) log.push(value);
    if (fail !== undefined && fail.on === value) throw fail.error;
    return value.toUpperCase();
  };
}

async function rejectsWith(promise, expected) {
  let caught;
  try {
    await promise;
  } catch (e) {
    caught = e;
  }
  assert.ok(caught, 'expected a rejection, got success');
  assert.equal(
    caught,
    expected,
    `expected the original error "${expected.message}", got ${caught && caught.constructor.name} "${caught && caught.message}"`,
  );
}

async function main() {
  // 1. Normal exhaustion: mapped records in order, lease closed exactly once.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const found = [];
    for await (const value of new EventService(source).stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B']);
    assert.equal(state.opens, 1);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a', 'b', 'END']);
    assert.deepEqual(state.closeLog, ['close']);
  }

  // 2. No lease is opened until the first iteration; a generator that is
  //    returned without having been iterated opens and closes nothing.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    assert.equal(state.opens, 0, 'stream() must not open the lease');
    await it.return(undefined);
    assert.equal(state.opens, 0, 'return() on an unopened generator must not open anything');
    assert.equal(state.closes, 0, 'return() on an unopened generator must not close anything');

    // An unopened generator that survives a throw() into it is also inert...
    // (the throw lands before the body ever ran) - checked separately, since
    // this iterator is spent after return().
    const fresh = makeSource(['a', null]);
    const it2 = new EventService(fresh.source).stream();
    const early = new Error('early');
    await rejectsWith(it2.throw(early), early);
    assert.equal(fresh.state.opens, 0);
    assert.equal(fresh.state.closes, 0);

    // First iteration must open exactly one lease.
    const late = makeSource(['a', null]);
    const it3 = new EventService(late.source).stream();
    assert.deepEqual(await it3.next(), { value: 'A', done: false });
    assert.equal(late.state.opens, 1, 'first next() opens exactly one lease');
    assert.equal(late.state.closes, 0, 'lease is still open mid-stream');
    await it3.return(undefined);
    assert.equal(late.state.closes, 1, 'ending the iteration closes the lease');
  }

  // 3. One read per next(), including exactly one read that establishes
  //    exhaustion; post-done next() must not read, re-open or re-close.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    assert.equal(state.readLog.length, 1, 'no read ahead of the first next()');
    assert.deepEqual(await it.next(), { value: 'B', done: false });
    assert.equal(state.readLog.length, 2, 'no read ahead while the consumer works');
    const third = await it.next();
    assert.equal(third.done, true);
    assert.equal(state.readLog.length, 3, 'exactly one read establishes exhaustion');
    assert.equal(state.closes, 1, 'lease closed by the exhausting next()');
    assert.deepEqual(await it.next(), { done: true, value: undefined }, 'post-done next() is inert');
    assert.equal(state.opens, 1, 'no re-open after done');
    assert.equal(state.closes, 1, 'no re-close after done');
  }

  // 4. Consumer break: closes the lease, never reads ahead past the break.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const found = [];
    for await (const value of new EventService(source).stream()) {
      found.push(value);
      break;
    }
    assert.deepEqual(found, ['A']);
    assert.equal(state.closes, 1);
    assert.equal(state.readLog.length, 1, "'b' was never read");
  }

  // 5. Manual return(): exactly one close, idempotent thereafter.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await it.return(undefined);
    assert.equal(state.closes, 1);
    await it.return(undefined);
    assert.equal(state.closes, 1, 'a second return() must not close again');
    assert.equal(state.readLog.length, 1, "'b' was never read");
    assert.deepEqual(await it.next(), { done: true, value: undefined });
    assert.equal(state.opens, 1, 'no re-open after return()');
    assert.equal(state.closes, 1, 'no re-close after return()');
  }

  // 6. Break with a failing close: the close failure surfaces (no original
  //    exception was in flight) rather than being swallowed by the break.
  {
    const C = new Error('C');
    const { source, state } = makeSource(['a', null], { failClose: C });
    await rejectsWith(
      (async () => {
        for await (const value of new EventService(source).stream()) {
          break;
        }
      })(),
      C,
    );
    assert.equal(state.closes, 1);
  }

  // 7. Exhaustion with a failing close: the close failure surfaces instead of
  //    ending the stream normally.
  {
    const C = new Error('C');
    const { source, state } = makeSource([null], { failClose: C });
    await rejectsWith(new EventService(source).stream().next(), C);
    assert.equal(state.closes, 1);
  }

  // 8. Source read failure: the original read exception wins over a failing
  //    close; the lease is closed exactly once and the stream is done.
  {
    const E = new Error('read!');
    const C = new Error('C');
    const { source, state } = makeSource(['a', E, null], { failClose: C });
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.next(), E);
    assert.equal(state.closes, 1, 'lease closed despite the read failure');
    assert.deepEqual(state.readLog, ['a', 'read!']);
    assert.deepEqual(await it.next(), { done: true, value: undefined }, 'generator stays done');
    assert.equal(state.closes, 1, 'no second close attempt');
  }

  // 9. Mapper failure on the first record: nothing is yielded, the mapper
  //    exception wins over a failing close, closes exactly once.
  {
    const M = new Error('M');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const mapperLog = [];
    const it = new EventService(source, makeMapper({ log: mapperLog, fixedFail: { on: 'a', error: M } })).stream();
    await rejectsWith(it.next(), M);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a']);
    assert.deepEqual(mapperLog, ['a']);
  }

  // 10. Mapper failure on a later record: earlier records were yielded, the
  //    mapper exception wins over a failing close, nothing is read afterwards.
  {
    const M = new Error('M');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const mapperLog = [];
    const it = new EventService(source, makeMapper({ log: mapperLog, fixedFail: { on: 'b', error: M } })).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.next(), M);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a', 'b']);
  }

  // 11. Consumer-injected throw via it.throw(): the injected exception wins
  //    over a failing close; closed exactly once.
  {
    const E = new Error('injected');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.throw(E), E);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a']);
  }

  // 12. Consumer-injected throw from the for-await body: the injected
  //    exception wins over a failing close; closed exactly once.
  {
    const E = new Error('injected');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    await rejectsWith(
      (async () => {
        for await (const value of new EventService(source).stream()) {
          if (value === 'A') throw E;
        }
      })(),
      E,
    );
    assert.equal(state.closes, 1);
    assert.equal(state.readLog.length, 1);
  }

  // 13. Open failure: first next() rejects with the open exception, no lease
  //    exists so nothing is closed, later next() calls stay done/inert.
  {
    const E = new Error('open!');
    const { source, state } = makeSource(['a', null], { failOpen: E });
    const it = new EventService(source).stream();
    await rejectsWith(it.next(), E);
    assert.equal(state.opens, 1);
    assert.equal(state.closes, 0);
    assert.deepEqual(await it.next(), { done: true, value: undefined });
    assert.equal(state.opens, 1, 'no re-open after the open failure');
    assert.equal(state.closes, 0);
  }

  // 14. Ordering stays intact across several records with a recording mapper.
  {
    const { source, state } = makeSource(['a', 'b', 'c', null]);
    const mapperLog = [];
    const found = [];
    for await (const value of new EventService(source, makeMapper({ log: mapperLog })).stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B', 'C']);
    assert.deepEqual(mapperLog, ['a', 'b', 'c']);
    assert.equal(state.closes, 1);
  }

  // 15. Interleaving: return()/throw() arriving while a next() is still in
  //    flight still closes the lease exactly once, still reads ahead nothing,
  //    and preserves the injected exception over a failing close.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    const pendingNext = it.next();
    const pendingReturn = it.return(undefined); // queued behind the pending next
    assert.deepEqual(await pendingNext, { value: 'A', done: false });
    assert.deepEqual(await pendingReturn, { done: true, value: undefined });
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a']);
  }

  {
    const E = new Error('race-throw');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const it = new EventService(source).stream();
    const pendingNext = it.next();
    const pendingThrow = it.throw(E); // queued behind the pending next
    assert.deepEqual(await pendingNext, { value: 'A', done: false });
    await rejectsWith(pendingThrow, E);
    assert.equal(state.closes, 1, 'injected error preserved over close failure');
    assert.deepEqual(state.readLog, ['a']);
  }

  // 16. return() after a close failure resolves instead of closing again.
  {
    const C = new Error('C');
    const { source, state } = makeSource([null], { failClose: C });
    const it = new EventService(source).stream();
    await rejectsWith(it.next(), C);
    assert.deepEqual(await it.return(undefined), { done: true, value: undefined });
    assert.equal(state.closes, 1);
  }
}
module.exports = main();

